const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const bytes=async b=>Array.from(new Uint8Array(await b.arrayBuffer())).join(',');


test('event-empty-dictionaries',()=>{for(const name of ['Event','CustomEvent','UIEvent','MouseEvent','PointerEvent','KeyboardEvent','FocusEvent','InputEvent','SubmitEvent','ProgressEvent','MessageEvent']){const Type=globalThis[name];for(const mode of ['omitted','undefined','null','object']){const seen=[];let value,result;for(const key of ['bubbles','cancelable','composed'])Object.defineProperty(Object.prototype,key,{configurable:true,get(){seen.push(key);return true}});try{value=mode==='omitted'?new Type('probe'):new Type('probe',mode==='undefined'?undefined:mode==='null'?null:{});result=String(value.bubbles)+' '+value.cancelable+' '+value.composed}catch(e){result=e.name}finally{for(const key of ['bubbles','cancelable','composed'])delete Object.prototype[key]}log(name,mode,seen.join(','),result)}}});
test('event-constructor-parents',()=>{for(const name of ['CustomEvent','UIEvent','MouseEvent','PointerEvent','KeyboardEvent','FocusEvent','InputEvent','SubmitEvent','ProgressEvent','MessageEvent']){const Type=globalThis[name],parent=Object.getPrototypeOf(Type);let calls=0,result;Object.setPrototypeOf(Type,function(){calls++;throw new Error('public parent')});try{result=new Type('probe')instanceof Type}catch(e){result=e.name}finally{Object.setPrototypeOf(Type,parent)}log(name,result,calls)}});
test('listener-empty-dictionaries',()=>{for(const mode of ['omitted','undefined','null','object']){const target=new EventTarget(),seen=[];let calls=0;for(const key of ['capture','once','passive','signal'])Object.defineProperty(Object.prototype,key,{configurable:true,get(){seen.push(key);return undefined}});try{const listener=()=>calls++;if(mode==='omitted')target.addEventListener('probe',listener);else target.addEventListener('probe',listener,mode==='undefined'?undefined:mode==='null'?null:{});target.dispatchEvent(new Event('probe'))}finally{for(const key of ['capture','once','passive','signal'])delete Object.prototype[key]}log(mode,seen.join(','),calls)}});
test('event-constructor-metadata',()=>{for(const name of ['Event','CustomEvent','UIEvent','MouseEvent','PointerEvent','WheelEvent','KeyboardEvent','FocusEvent','InputEvent','SubmitEvent','ProgressEvent','HashChangeEvent','PopStateEvent','ErrorEvent','ToggleEvent','MessageEvent']){const Type=globalThis[name];let required,plain;try{new Type();required='accepted'}catch(e){required=e.name}try{Type('probe');plain='accepted'}catch(e){plain=e.name}log(name,Type.name,Type.length,Object.prototype.toString.call(new Type('probe')),required,plain)}});
test('event-dictionary-order',()=>{const fields=new Set('bubbles cancelable composed detail view altKey button buttons clientX clientY ctrlKey metaKey movementX movementY relatedTarget screenX screenY shiftKey pointerId width height pressure tangentialPressure tiltX tiltY twist pointerType isPrimary altitudeAngle azimuthAngle modifierAltGraph modifierCapsLock modifierFn modifierFnLock modifierHyper modifierNumLock modifierScrollLock modifierSuper modifierSymbol modifierSymbolLock code key location repeat isComposing charCode keyCode data dataTransfer inputType targetRanges submitter lengthComputable loaded total oldURL newURL state colno filename lineno message error oldState newState source origin lastEventId ports'.split(' '));for(const name of ['Event','CustomEvent','UIEvent','MouseEvent','PointerEvent','WheelEvent','KeyboardEvent','FocusEvent','InputEvent','SubmitEvent','ProgressEvent','HashChangeEvent','PopStateEvent','ErrorEvent','ToggleEvent','MessageEvent']){const seen=[];try{new globalThis[name]('probe',new Proxy({},{get(o,k){if(fields.has(k))seen.push(k);return undefined}}));log(name,seen.join(','))}catch(e){log(name,e.name,seen.join(','))}}});
test('event-scalar-conversion',()=>{const cases=[['UIEvent',{detail:-2.9},['detail','view']],['MouseEvent',{button:65535,buttons:65537,clientX:2.9,screenY:-2.9},['button','buttons','clientX','screenY']],['PointerEvent',{},['pointerId','pointerType','isPrimary','width','height','pressure','tiltX','twist']],['PointerEvent',{pointerId:2.9,width:1.9,height:3,pressure:0.5},['pointerId','width','height','pressure']],['KeyboardEvent',{key:7,code:5,location:2.9,repeat:1,isComposing:1},['key','code','location','repeat','isComposing']],['ProgressEvent',{loaded:3.7,total:'9.8',lengthComputable:1},['loaded','total','lengthComputable']],['HashChangeEvent',{oldURL:null,newURL:7},['oldURL','newURL']],['InputEvent',{data:7,inputType:8,isComposing:1},['data','inputType','isComposing']]];for(const[name,init,keys]of cases)try{const e=new globalThis[name]('probe',init);log(name,keys.map(k=>k+'='+String(e[k])).join(','))}catch(e){log(name,e.name)}});
test('event-private-click',()=>{const button=document.createElement('button');button.textContent='tap';document.body.appendChild(button);let reads=0,seen;button.addEventListener('click',e=>{seen=[e.type,e.pointerId,e.pointerType,e.isPrimary,e.detail].join(',')});for(const key of ['pointerType','isPrimary','width','height','pressure','relatedTarget','screenX'])Object.defineProperty(Object.prototype,key,{configurable:true,get(){reads++;return undefined}});try{button.click()}finally{for(const key of ['pointerType','isPrimary','width','height','pressure','relatedTarget','screenX'])delete Object.prototype[key]}button.remove();log(seen,reads)});
test('event-readonly-and-brand',()=>{for(const[name,key]of [['UIEvent','detail'],['MouseEvent','clientX'],['PointerEvent','pointerId'],['KeyboardEvent','key'],['ProgressEvent','loaded'],['InputEvent','data']]){const Type=globalThis[name],e=new Type('probe');let proto=Type.prototype,desc;while(proto&&!desc){desc=Object.getOwnPropertyDescriptor(proto,key);proto=Object.getPrototypeOf(proto)}let wrong;try{if(desc&&desc.get)desc.get.call(new Event('probe'));else throw new Error('missing accessor');wrong='accepted'}catch(e){wrong=e.name}const before=e[key];try{e[key]=99}catch{}log(name,key,String(e[key])===String(before),Object.hasOwn(e,key),wrong)}});
test('event-numeric-domains',()=>{for(const name of ['MouseEvent','PointerEvent'])for(const value of [-2.9,-1,6,65535,Infinity,NaN])try{const e=new globalThis[name]('probe',{button:value,clientX:value,screenY:value});log(name,String(value),e.button,e.clientX,e.screenY)}catch(e){log(name,String(value),e.name)}for(const name of ['ProgressEvent','PointerEvent'])for(const value of [0.3,Infinity,NaN])try{const e=new globalThis[name]('probe',name==='ProgressEvent'?{loaded:value,total:value}:{pressure:value,width:value});log(name,String(value),e.loaded??e.pressure,e.total??e.width)}catch(e){log(name,String(value),e.name)}});
test('event-promise-required',()=>{for(const[label,value]of [['missing',undefined],['null',null],['number',0],['object',{}],['promise',Promise.resolve(1)]])try{const init=label==='missing'?{}:{promise:value};const e=new PromiseRejectionEvent('probe',init);log(label,'ok',e.promise===value,typeof e.promise.then)}catch(e){log(label,e.name)}});
test('event-coordinates',()=>{for(const name of ['MouseEvent','PointerEvent','WheelEvent','DragEvent']){const e=new globalThis[name]('probe',{clientX:2.9,clientY:-2.9,screenX:3.5,screenY:-3.5});log(name,['clientX','clientY','screenX','screenY','pageX','pageY','x','y','offsetX','offsetY','movementX','movementY'].map(k=>k+'='+e[k]).join(','))}});
test('event-pointer-orientation',()=>{for(const init of [{},{tiltX:45},{tiltY:45},{tiltX:90,tiltY:0},{altitudeAngle:Math.PI/4,azimuthAngle:0},{altitudeAngle:Math.PI/4,azimuthAngle:Math.PI/2}]){const e=new PointerEvent('probe',init);log(JSON.stringify(init),[e.tiltX,e.tiltY,e.altitudeAngle,e.azimuthAngle].map(v=>Math.round(v*1e8)/1e8).join(','))}});
test('event-internal-promise',()=>new Promise(resolve=>{let calls=0;const rejected=Promise.reject('probe');Object.defineProperty(rejected,'constructor',{configurable:true,get(){calls++;return Promise}});onunhandledrejection=e=>{e.preventDefault();log(e.promise===rejected,calls);onunhandledrejection=null;resolve()}}));
test('event-focus-fields',()=>{const a=document.createElement('input'),b=document.createElement('input');a.id='one';b.id='two';document.body.append(a,b);const seen=[];for(const type of ['focus','focusin','blur','focusout'])for(const node of [a,b])node.addEventListener(type,e=>seen.push([e.type,node.id,e.relatedTarget?.id??'',e.bubbles,e.composed,e.view===window].join(',')));a.focus();b.focus();b.blur();a.remove();b.remove();for(const row of seen)log(row)});
