test('event-reflect-order',()=>{for(const name of ['Event','CustomEvent','MouseEvent','MessageEvent']){const seen=[],type={toString(){seen.push('type');return 'probe'}},init={get bubbles(){seen.push('bubbles');return false}},Target=new Proxy(function(){},{get(o,k,r){if(k==='prototype')seen.push('prototype');return Reflect.get(o,k,r)}});Reflect.construct(globalThis[name],[type,init],Target);log(name,seen.join(','))}});
