test('event-private-brand-record',()=>{const proto=Object.prototype;let calls=0;for(const key of ['custom','detail','formData','mouse'])Object.defineProperty(proto,key,{configurable:true,get(){calls++;return true}});let custom,form;try{const event=new Event('probe');try{Object.getOwnPropertyDescriptor(CustomEvent.prototype,'detail').get.call(event);custom='accepted'}catch(e){custom=e.name}try{Object.getOwnPropertyDescriptor(FormDataEvent.prototype,'formData').get.call(event);form='accepted'}catch(e){form=e.name}new EventTarget().dispatchEvent(event)}finally{for(const key of ['custom','detail','formData','mouse'])delete proto[key]}log(custom,form,calls)});
