test('event-focusability',()=>{for(const[label,tag,attrs,attach]of [['input','input',{},true],['disabled','input',{disabled:''},true],['hidden-input','input',{type:'hidden'},true],['div','div',{},true],['tab','div',{tabindex:'-1'},true],['bad-tab','div',{tabindex:'bad'},true],['anchor','a',{href:'#'},true],['no-href','a',{},true],['hidden','input',{hidden:''},true],['inert','input',{inert:''},true],['detached','input',{},false]]){const e=document.createElement(tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(attach)document.body.appendChild(e);let count=0;e.addEventListener('focus',()=>count++);e.focus();log(label,document.activeElement===e,count);e.blur();e.remove()}});
